{"implementation":"import math


def _finite_number(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(field + " must be a number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(field + " must be finite")
    return value


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case is missing required fields")

    threshold = _finite_number(case["threshold"], "threshold")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    accepted_call_ids = []
    diagnostics = []

    for index, call in enumerate(calls):
        prefix = "calls[" + str(index) + "]"
        if not isinstance(call, dict):
            raise ValueError(prefix + " must be an object")

        required = (
            "call_id",
            "loss_without_call",
            "loss_with_call",
            "prediction_tokens",
            "parseable",
        )
        if any(field not in call for field in required):
            raise ValueError(prefix + " is missing required fields")

        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError(prefix + ".call_id must be a string")

        loss_without = _finite_number(
            call["loss_without_call"], prefix + ".loss_without_call"
        )
        loss_with = _finite_number(
            call["loss_with_call"], prefix + ".loss_with_call"
        )
        if loss_without < 0 or loss_with < 0:
            raise ValueError(prefix + " losses must be nonnegative")

        prediction_tokens = call["prediction_tokens"]
        if (
            isinstance(prediction_tokens, bool)
            or not isinstance(prediction_tokens, int)
            or prediction_tokens < 0
        ):
            raise ValueError(prefix + ".prediction_tokens must be a nonnegative integer")

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError(prefix + ".parseable must be a boolean")

        normalized_gain = (loss_without - loss_with) / max(1, prediction_tokens)
        accepted = parseable and normalized_gain >= threshold

        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append(
            {
                "accepted": accepted,
                "call_id": call_id,
                "normalized_gain": round(normalized_gain, 6),
            }
        )

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
"}
